{
  "schema_version": 1,
  "template_id": "gtm-strategy-analyst",
  "template_version": 1,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm GTM role and owner",
      "instructions": "Confirm whether GTM Strategy Analyst is the Crew’s primary role or a supporting capability. Preserve an existing identity and name the accountable GTM owner."
    },
    {
      "id": "skill",
      "title": "Verify the selected skill",
      "instructions": "Confirm skills/gtm-strategy-analyst/SKILL.md exists and gtm-strategy-analyst is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Set offer, audience, and launch scope",
      "instructions": "Record the offer version, audience, market, budget, dates, owner, first job, and exclusions. Minimum input: Offer and product claims, target buyer and market, customer or research evidence, available site and channels, budget, owner, and qualified-pipeline goal."
    },
    {
      "id": "access",
      "title": "Test source and channel access",
      "instructions": "Read a representative authorized source or export and record account, ID, freshness, and field coverage. Public and authorized customer research, website analytics, Search Console, CRM, campaign reports, and product material; supplied documents support a first read-only brief. A named SaaS provider is not verified access."
    },
    {
      "id": "policy",
      "title": "Agree on claims and pipeline rules",
      "instructions": "Confirm approved product claims, channel and contact policy, qualified lead and meeting definitions, baseline or baseline-first rule, attribution limits, and review owner."
    },
    {
      "id": "first_result",
      "title": "Produce the first sourced result",
      "instructions": "Use actual authorized evidence to produce A launch brief with approved offer and audience, evidence-backed buyer problem, message hypotheses, chosen channels, owner, metric definitions, and open decisions. Every material buyer or product claim needs an owner-approved source; a proposed campaign goal is not an observed pipeline outcome. The fictional example does not complete this check."
    },
    {
      "id": "review",
      "title": "Review the result and next action",
      "instructions": "Show source-linked facts, hypotheses, unknowns, exact proposed actions, owner, and approval boundaries. Record the owner decision."
    },
    {
      "id": "delivery",
      "title": "Choose publishing and delivery routes",
      "optional": true,
      "instructions": "Choose read-only chat or separately authorized CMS, campaign, CRM, and message actions. Read-only chat completes this decision. Do not publish positioning, launch campaigns, spend budget, scrape personal contacts, or treat research interest as contact permission without an authorized route and review."
    },
    {
      "id": "recurrence",
      "title": "Choose repeat and Automation route",
      "optional": true,
      "instructions": "Choose manual-only or a reviewed event or schedule with deduplication and cost rules. Manual-only completes this decision. On a later run, compare new customer and pipeline evidence against the recorded hypothesis and metric rule; preserve previous decisions and avoid rewriting history from one campaign result."
    }
  ],
  "completed_steps": []
}

